use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 1
    let mut first = true
    // keys ordered least recent -> most recent
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < keys.len() {
                if keys[i] != k {
                    nk.push(keys[i])
                    nv.push(vals[i])
                }
                i += 1
            }
            nk.push(k)
            nv.push(v)
            if nk.len() as int > cap {
                println("evict ${nk[0]}")
                let mut ek: Vec<int> = []
                let mut ev: Vec<int> = []
                let mut j = 1
                while j < nk.len() {
                    ek.push(nk[j])
                    ev.push(nv[j])
                    j += 1
                }
                nk = ek
                nv = ev
            }
            keys = nk
            vals = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    found = vals[i]
                } else {
                    nk.push(keys[i])
                    nv.push(vals[i])
                }
                i += 1
            }
            if found != -1 || keys.len() != nk.len() {
                nk.push(k)
                nv.push(found)
                keys = nk
                vals = nv
            }
            println("${found}")
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = keys.len() as int - 1
                while i >= 0 {
                    if out != "" {
                        out = out + " "
                    }
                    out = out + "${keys[i as usize]}"
                    i -= 1
                }
                println("${out}")
            }
        }
    }
}

